func:
// Rule Engine: Giám sát ngưỡng chất lượng nước và ra quyết định điều khiển sục khí
// Input: msg.payload từ Orion Context Broker (NGSI-v2 Subscription)

const data = msg.payload.data;
if (!Array.isArray(data) || data.length === 0) {
    return null;
}

// Hàm trích xuất giá trị thuộc tính (hỗ trợ cả keyValues và normalized format)
function getAttrValue(entity, attrName) {
    if (!entity || entity[attrName] === undefined || entity[attrName] === null) return null;
    if (typeof entity[attrName] === 'object' && entity[attrName] !== null && 'value' in entity[attrName]) {
        return entity[attrName].value;
    }
    return entity[attrName];
}

const commands = [];
const alerts = [];

for (let i = 0; i < data.length; i++) {
    const pond = data[i];
    const pondId = pond.id; // ví dụ: urn:ngsi-ld:Pond:001
    const doVal = getAttrValue(pond, 'dissolvedOxygen');
    const phVal = getAttrValue(pond, 'pH');
    const tempVal = getAttrValue(pond, 'temperature');
    const salVal = getAttrValue(pond, 'salinity');
    const aeratorState = (getAttrValue(pond, 'aeratorState') || '').toUpperCase();

    let targetAerator = null;
    let triggerReason = '';

    // RULE 1: Nhiệt độ cao (> 33°C) -> Cảnh báo + kích hoạt sục khí
    if (tempVal !== null && tempVal > 33.0) {
        alerts.push({
            pondId: pondId,
            level: 'WARNING',
            metric: 'temperature',
            value: tempVal,
            message: `[${pondId}] Nhiệt độ nước cao (${tempVal}°C > 33°C). Bật sục khí hỗ trợ!`,
            timestamp: new Date().toISOString()
        });
        targetAerator = 'ON';
        triggerReason = `Nhiệt độ cao (${tempVal}°C)`;
    }

    // RULE 2: Ngưỡng Oxy hòa tan (DO)
    // - DO < 4.0 mg/L -> Bật sục khí
    // - DO > 6.0 mg/L -> Tắt sục khí (Hysteresis chống giật rơ-le)
    if (doVal !== null) {
        if (doVal < 4.0) {
            targetAerator = 'ON';
            triggerReason = `DO thấp (${doVal} mg/L < 4.0 mg/L)`;
            if (doVal < 2.5) {
                alerts.push({
                    pondId: pondId,
                    level: 'CRITICAL',
                    metric: 'dissolvedOxygen',
                    value: doVal,
                    message: `[${pondId}] NGUY CẤP! DO tụt sâu (${doVal} mg/L < 2.5 mg/L). Đang bật sục khí khẩn cấp!`,
                    timestamp: new Date().toISOString()
                });
            } else {
                alerts.push({
                    pondId: pondId,
                    level: 'WARNING',
                    metric: 'dissolvedOxygen',
                    value: doVal,
                    message: `[${pondId}] Cảnh báo: DO thấp (${doVal} mg/L < 4.0 mg/L). Bật sục khí.`,
                    timestamp: new Date().toISOString()
                });
            }
        } else if (doVal > 6.0 && (tempVal === null || tempVal <= 33.0)) {
            targetAerator = 'OFF';
            triggerReason = `DO dồi dào (${doVal} mg/L > 6.0 mg/L)`;
        }
    }

    // RULE 3: pH bất thường ngoài khoảng 7.5 - 8.5
    if (phVal !== null && (phVal < 7.5 || phVal > 8.5)) {
        alerts.push({
            pondId: pondId,
            level: 'WARNING',
            metric: 'pH',
            value: phVal,
            message: `[${pondId}] Cảnh báo: pH bất thường (${phVal} nằm ngoài 7.5 - 8.5)!`,
            timestamp: new Date().toISOString()
        });
    }

    // Chỉ gửi lệnh khi cần chuyển đổi trạng thái thực sự (tránh spam lệnh)
    if (targetAerator !== null && targetAerator !== aeratorState) {
        commands.push({
            url: `http://orion:1026/v2/entities/${encodeURIComponent(pondId)}/attrs`,
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'fiware-service': 'shrimp',
                'fiware-servicepath': '/'
            },
            payload: {
                'aerator': {
                    'type': 'command',
                    'value': targetAerator
                }
            },
            info: `[${pondId}] Chuyển aerator từ ${aeratorState || 'UNKNOWN'} sang ${targetAerator} do ${triggerReason}`,
            pondId: pondId,
            targetAerator: targetAerator
        });
    }
}

// Output 1: Danh sách các lệnh điều khiển gửi tới Orion
// Output 2: Danh sách các cảnh báo (Alerts)
const alertMsg = alerts.length > 0 ? { payload: alerts } : null;
return [commands, alertMsg];
